import 'api_client.dart';class CatalogApi{CatalogApi(this.client);final ApiClient client;Future<List<dynamic>> list(String path,{Map<String,dynamic>? query})async{final r=(await client.dio.get(path,queryParameters:query)).data['data'];return r is Map?(r['data']??[]) : (r as List);}Future<Map<String,dynamic>> detail(String path)async=>((await client.dio.get(path)).data['data'] as Map<String,dynamic>);}
